from __future__ import annotations
from math import gcd
from typing import List, Optional, Tuple


def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True


def verify_certificate(k: int, cert: List[Tuple[int, int, int]]) -> bool:
    """Sound verifier for a Sierpinski covering certificate.

    cert is a list of (residue a, modulus m, prime p). Returns True iff:
      (i) each p is prime, (ii) p | k*2^a + 1, (iii) 2^m = 1 (mod p),
      (iv) the classes cover every residue modulo L = lcm of moduli.
    A True verdict certifies (via certificate_gives_divisor and
    covering_finite_verification) that every k*2^n + 1 has a fixed small divisor.
    """
    L = 1
    for (_a, m, _p) in cert:
        L = lcm(L, m)
    for (a, m, p) in cert:
        if not is_prime(p):
            return False
        if (k * pow(2, a, p) + 1) % p != 0:
            return False
        if pow(2, m, p) != 1:
            return False
    for n in range(L):
        if not any(n % m == a and (k * pow(2, n, p) + 1) % p == 0
                   for (a, m, p) in cert):
            return False
    return True


def covering_witness(k: int, cert: List[Tuple[int, int, int]], n: int) -> Optional[int]:
    """Return the covering prime for exponent n (mirrors certificate_gives_divisor)."""
    for (a, m, p) in cert:
        if n % m == a and (k * pow(2, n, p) + 1) % p == 0:
            return p
    return None

from __future__ import annotations
from math import gcd
from typing import Dict, List, Optional, Tuple


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True


def order_of_two(p: int) -> int:
    m, v = 1, 2 % p
    while v != 1:
        v = (v * 2) % p
        m += 1
    return m


def synthesize_certificate(
    k: int, period: int, prime_bound: int = 200
) -> Optional[List[Tuple[int, int, int]]]:
    """Greedy synthesizer: try to build a covering certificate of given period.

    For each still-uncovered residue r mod `period`, search small primes p with
    ord_p(2) | period and p | k*2^r + 1; assign p to the whole arithmetic
    progression r mod ord_p(2). The output (if any) is intended to be passed to
    `verify_certificate`, realizing the find/check separation.
    """
    small_primes: List[int] = [p for p in range(3, prime_bound + 1) if is_prime(p)]
    covered: List[bool] = [False] * period
    cert: List[Tuple[int, int, int]] = []
    for r in range(period):
        if covered[r]:
            continue
        chosen: Optional[Tuple[int, int]] = None
        for p in small_primes:
            if period % order_of_two(p) != 0:
                continue
            if (k * pow(2, r, p) + 1) % p == 0:
                chosen = (order_of_two(p), p)
                break
        if chosen is None:
            return None
        m, p = chosen
        cert.append((r % m, m, p))
        for j in range(r % m, period, m):
            covered[j] = True
    return cert if all(covered) else None
